import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        String s = scanner.next();
        int m = s.length();

        // Precompute KMP prefix function for pattern s
        int[] pi = new int[m];
        for (int i = 1; i < m; i++) {
            int j = pi[i - 1];
            while (j > 0 && s.charAt(i) != s.charAt(j)) {
                j = pi[j - 1];
            }
            if (s.charAt(i) == s.charAt(j)) {
                j++;
            }
            pi[i] = j;
        }

        // dp[i][j] = number of ways to form a string of length i such that the longest suffix
        // which is a prefix of s has length j, and s has NOT appeared as a substring yet.
        // We use long to avoid overflow, though the final answer fits in int for n<=40.
        long[][] dp = new long[n + 1][m];

        // Base case: empty string, prefix length 0
        dp[0][0] = 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (dp[i][j] == 0) continue;

                // Try appending '0'
                int nextJ = transition(j, '0', s, pi);
                if (nextJ < m) {
                    dp[i + 1][nextJ] += dp[i][j];
                }

                // Try appending '1'
                nextJ = transition(j, '1', s, pi);
                if (nextJ < m) {
                    dp[i + 1][nextJ] += dp[i][j];
                }
            }
        }

        // Total number of binary strings of length n that do NOT contain s
        long notContaining = 0;
        for (int j = 0; j < m; j++) {
            notContaining += dp[n][j];
        }

        long total = 1L << n;
        long containing = total - notContaining;

        System.out.println(containing);
    }

    private static int transition(int currentPrefixLen, char c, String s, int[] pi) {
        int j = currentPrefixLen;
        while (j > 0 && s.charAt(j) != c) {
            j = pi[j - 1];
        }
        if (s.charAt(j) == c) {
            j++;
        }
        return j;
    }
}

